// Code calculates every number in the report.
const n = $('Funnel, replies and costs').first().json;
const pipes = $('HubSpot: deal stages').first().json.results || [];
const pipe = pipes.find(p => p.id === 'YOUR_PIPELINE_ID') || pipes.find(p => p.id === 'default') || pipes[0] || { stages: [] };
const stage = Object.fromEntries((pipe.stages || []).map(s => [s.id, { label: s.label, p: Number(s.metadata?.probability ?? 0), order: s.displayOrder }]));
const deals = ($('HubSpot: open deals').first().json.results || []).filter(d => stage[d.properties.dealstage]);
const byStage = {};
let weighted = 0, openValue = 0;
for (const d of deals) {
  const s = stage[d.properties.dealstage];
  const amt = Number(d.properties.amount || 0);
  byStage[s.label] = byStage[s.label] || { order: s.order, count: 0, value: 0 };
  byStage[s.label].count++; byStage[s.label].value += amt;
  openValue += amt; weighted += amt * s.p;
}
const leads = n.leads_by_source || {};
const cust = {}; let restaurants = 0, households = 0;
for (const r of n.new_customers || []) {
  cust[r.source] = (cust[r.source] || 0) + Number(r.n);
  if (['restaurant', 'hotel', 'caterer'].includes(r.segment)) restaurants += Number(r.n); else households += Number(r.n);
}
const totalCust = restaurants + households;
const totalLeads = Object.values(leads).reduce((a, b) => a + Number(b), 0);
const costs = n.costs || {};
const totalCost = Object.values(costs).reduce((a, b) => a + Number(b), 0);
const channels = [...new Set([...Object.keys(leads), ...Object.keys(cust), ...Object.keys(costs)])].filter(c => c !== 'shared' && c !== 'unknown');
const perChannel = channels.map(ch => ({
  channel: ch, leads: Number(leads[ch] || 0), customers: Number(cust[ch] || 0), cost_ngn: Number(costs[ch] || 0),
  cost_per_lead: leads[ch] ? Math.round(Number(costs[ch] || 0) / leads[ch]) : null,
  cost_per_customer: cust[ch] ? Math.round(Number(costs[ch] || 0) / cust[ch]) : null
}));
const conversion = (n.conversion || []).filter(c => Number(c.leads) >= 1).map(c => ({ source: c.source, pct: Math.round(100 * c.converted / c.leads), leads: Number(c.leads) }));
const replies = (n.replies || []).filter(r => r.kind !== 'complaint').map(r => ({ channel: r.channel, min: Number(r.median_min) }));
const complaintReply = (n.replies || []).filter(r => r.kind === 'complaint').map(r => Number(r.median_min));
const e = n.email || {};
return [{ json: {
  data_ok: Number(n.events_week) > 0 && (totalLeads > 0 || totalCust > 0),
  new_customers: totalCust, restaurants, households, by_first_touch: cust, leads_by_source: leads, total_leads: totalLeads,
  conversion, replies, complaint_reply_min: complaintReply.length ? Math.max(...complaintReply) : null,
  per_channel: perChannel, total_cost_ngn: Math.round(totalCost), overall_cost_per_customer: totalCust ? Math.round(totalCost / totalCust) : null,
  pipeline: Object.entries(byStage).sort((a, b) => a[1].order - b[1].order).map(([label, v]) => ({ stage: label, deals: v.count, value_ngn: Math.round(v.value) })),
  open_pipeline_ngn: Math.round(openValue), weighted_forecast_ngn: Math.round(weighted),
  complaint_rate_pct: e.delivered ? +(100 * e.complaints / e.delivered).toFixed(2) : 0,
  unsubscribe_rate_pct: e.delivered ? +(100 * e.unsubscribes / e.delivered).toFixed(1) : 0,
  complaints_inbox: Number(n.complaints_inbox), unsubscribes_all: Number(n.unsubscribes_all), rule_breaches: Number(n.rule_breaches)
} }];

const r = $('Compute report').first().json;
const naira = x => x === null || x === undefined ? 'n/a' : '₦' + Math.round(x).toLocaleString('en-NG');
const cap = s => String(s).charAt(0).toUpperCase() + String(s).slice(1);
const sorted = Object.entries(r.by_first_touch).sort((a, b) => b[1] - a[1]);
const lines = [
  `📈 Harvest Lane · growth · week to ${$now.setZone('Africa/Lagos').toFormat('d LLL')}`,
  `New customers: ${r.new_customers} (restaurants ${r.restaurants} · households ${r.households})`,
  `By first touch: ${sorted.map(([k, v]) => `${cap(k)} ${v}`).join(' · ') || 'none'}`,
  `New leads: ${r.total_leads} (${Object.entries(r.leads_by_source).map(([k, v]) => `${k} ${v}`).join(' · ') || 'none'})`,
  `Lead → first order (90 days): ${r.conversion.map(c => `${c.source} ${c.pct}%`).join(' · ') || 'n/a'}`,
  `Median first reply: ${r.replies.map(x => `${cap(x.channel)} ${x.min} min`).join(' · ') || 'n/a'}${r.complaint_reply_min !== null ? ` · complaints ${r.complaint_reply_min} min (person)` : ''}`,
  `Cost per lead: ${r.per_channel.filter(c => c.cost_per_lead !== null).map(c => `${c.channel} ${naira(c.cost_per_lead)}`).join(' · ') || 'n/a'}`,
  `Cost per new customer: ${r.per_channel.filter(c => c.cost_per_customer !== null).map(c => `${c.channel} ${naira(c.cost_per_customer)}`).join(' · ') || 'n/a'} · overall ${naira(r.overall_cost_per_customer)}`,
  `Pipeline: ${r.pipeline.map(s => `${s.stage} ${s.deals} (${naira(s.value_ngn)})`).join(' · ') || 'no open deals'}`,
  `Open pipeline ${naira(r.open_pipeline_ngn)} · weighted forecast ${naira(r.weighted_forecast_ngn)}`,
  `Complaints ${r.complaint_rate_pct}% · unsubscribes ${r.unsubscribe_rate_pct}% · inbox complaints ${r.complaints_inbox} · ${r.rule_breaches ? r.rule_breaches + ' rule breach(es) ⚠️' : 'no rule breaches'}`,
  `Recommendation: ${String($input.first().json.text || '').trim()}`
];
return [{ json: { text: lines.join('\n') } }];
